css:
/* widget全体の設定 */
.stepList__area {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
}



/* 見出し部分 */
.head__box {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
}



/* 見出し */
.head__box .head {
  /* 文字の大きさ */
  font-size: 38px;
  /* 文字の色 */
  color: #333;
  /* 文字の位置 */
  text-align: center;
}



/* 下線 */
.head .underLine {
  /* 下線｜太さ｜線種｜色｜ */
  border-bottom: 1px solid #333;
  /* 内側の下余白 */
  padding-bottom: 5px;
}



/* テキストのグラデーション部分 */
.head .grade {
  /* 文字の大きさ */
  font-size: 44px;
  /* 文字の太さ */
  font-weight: bold;
  /* 高さ */
  height: 100% !important;
  display: inline-block;
  /* 行間 */
  line-height: 1;
  /* 文字の色 */
  color: #e57ea2;
  /* 背景色（文字のグラデーション） */
  background: linear-gradient(90deg, #e686a6, #db3e7b);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  position: relative;
}



/* グラデーションテキストの後ろの下線 */
.head .underLineBold:before {
  content: '';
  /* 横幅 */
  width: calc(100% + 10px);
  /* 高さ */
  height: 20px;
  /* 背景色 */
  background: #f7ebeb;
  /* 回転 */
  transform: rotate(-4deg);
  display: inline-block;
  position: absolute;
  /* 表示位置（下基準） */
  bottom: -5px;
  /* 表示位置（左基準） */
  left: -5px;
  z-index: -1;
}



/* 見出しの大きい文字 */
.head ._big {
  /* 文字の大きさ */
  font-size: 60px;
}



/* コンテンツの全体の設定 */
.items__box {
  display: flex;
  justify-content: center;
  align-items: flex-start;
  margin-top: 30px;
}



/* コンテンツ一つの設定 */
.item {
  /* 横幅 */
  width: 29%;
  /* 高さ */
  height: auto;
  /* 外側の右余白 */
  margin-right: 6.46%;
  position: relative;
}



/* コンテンツの一番最後の箱 */
.item:last-of-type {
  /* 外側の右余白 */
  margin-right: 0;
}



/* 順番の数字部分 */
.item .num {
  /* 文字の大きさ */
  font-size: 20px;
  /* 文字の太さ */
  font-weight: bold;
  /* 横幅 */
  width: 36px;
  /* 高さ */
  height: 36px;
  /* 文字の色 */
  color: #333;
  /* 線｜太さ｜線種｜色｜ */
  border: 1px solid #333;
  /* 線｜太さ｜線種｜色｜ */
  border-radius: 19px;
  /* 背景色 */
  background: #fff;
  /* 文字の位置 */
  text-align: center;
  /* 行間 */
  line-height: 1.7;
  position: absolute;
  /* 表示位置（上基準） */
  top: -18px;
  /* 表示位置（左基準） */
  left: -18px;
  /* 外側の余白 */
  margin: 0;
  z-index: 2;
}



/* 画像の箱 */
.img__box {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
  /* 線｜太さ｜線種｜色｜ */
  border: 1px solid #333;
  position: relative;
}



/* 矢印 */
.img__box:after {
  content: '';
  /* 横幅 */
  width: 10px;
  /* 高さ */
  height: 10px !important;
  /* 線｜太さ｜線種｜色｜ */
  border-top: 1px solid #333;
  /* 線｜太さ｜線種｜色｜ */
  border-right: 1px solid #333;
  display: inline-block;
  position: absolute;
  /* 表示位置（上基準） */
  top: 50%;
  /* 表示位置（右基準） */
  right: -10.5%;
  /* 回転、位置 */
  transform: rotate(45deg) translateY(-50%);
}



/* 最後のコンテンツの矢印非表示 */
.item:last-of-type .img__box:after {
  content: none;
}



/* 画像 */
.img__box img {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
  display: block;
}



/* テキスト部分 */
.item .text {
  /* 外側の余白 */
  margin: 10px 0 0;
  /* 文字の位置 */
  text-align: center;
  /* 文字の色 */
  color: #333;
  /* 文字の大きさ */
  font-size: 16px;
}

/* レスポンシブ（初期600px） */
@media screen and (max-width: 600px) {


  /* 見出し */
  .head__box .head {
    /* 文字の大きさ */
    font-size: 22px;
  }



  /* グラデーション部分 */
  .head .grade {
    /* 文字の大きさ */
    font-size: 30px;
  }



  /* グラデーション部分の下線 */
  .head .underLineBold:before {
    content: '';
    /* 横幅 */
    width: calc(100% + 10px);
    /* 高さ */
    height: 15px;
    /* 表示位置（下基準） */
    bottom: -3px;
  }



  /* 見出しの大きい文字 */
  .head ._big {
    /* 文字の大きさ */
    font-size: 36px;
  }



  /* コンテンツ部分の設定 */
  .items__box {
    /* 要素がはみ出る場合は改行 */
    flex-wrap: wrap;
    /* 外側の上余白 */
    margin-top: 30px;
  }



  /* コンテンツ */
  .item {
    /* 横幅 */
    width: 80%;
    /* 外側の余白 */
    margin: 20px 0 40px 0;
    position: relative;
  }



  /* 矢印 */
  .item:after {
    content: '';
    /* 横幅 */
    width: 15px;
    /* 高さ */
    height: 15px;
    /* 下線｜太さ｜線種｜色｜ */
    border-bottom: 1px solid #333;
    /* 右線｜太さ｜線種｜色｜ */
    border-right: 1px solid #333;
    display: inline-block;
    position: absolute;
    /* 表示位置（下基準） */
    bottom: -30px;
    /* 表示位置（左基準） */
    left: 50%;
    /* 回転、位置 */
    transform: rotate(45deg) translateX(-50%);
  }



  /* 最後のコンテンツは矢印非表示 */
  .item:last-of-type:after {
    content: none;
  }



  /* PC時表示していた矢印を非表示 */
  .img__box:after {
    content: none;
  }



  /* テキスト部分 */
  .item .text {
    /* 外側の余白 */
    margin: 10px 0 0;
    /* 文字の位置 */
    text-align: center;
    /* 文字の色 */
    color: #333;
    /* 文字の大きさ */
    font-size: 14px;
  }
}

/* 全体の設定 */
.calc-difference {
  /* 最大幅 */
  max-width: 600px;
  /* 外側の余白｜上下｜左右（センタリング）｜ */
  margin: 0 auto;
  box-sizing: border-box;
  /* 文字の位置 */
  text-align: center;
}



/* widgetの見出し部分 */
.calc-difference .title {
  display: inline-block;
  /* 文字の位置 */
  text-align: center;
  /* 文字の色 */
  color: #ffffff;
  /* 背景色 */
  background: #000000;
  /* 角丸 */
  border-radius: 2em;
  /* 内側の余白｜上下｜左右｜ */
  padding: 0.6em 1.4em;
  /* 外側の余白｜上下｜左右｜ */
  margin: 1em 0;
}



/* 選択肢のリスト部分 */
.calc-difference .list-radio {
  /* リストスタイル */
  list-style-type: none;
  /* 外側の余白 */
  margin: 0;
  /* 内側の余白 */
  padding: 0;
  box-sizing: border-box;
  display: flex;
  /*水平方向に間隔を配置する方法。
      flex-start = 左側から配置する
      flex-end = 右側から配置する
      center = 真ん中に配置する
      space-around = 均等配置して両端に間隔を置く
      space-between = 均等配置してエリアの間に間隔を置く
      space-evenly = 均等配置して各アイテム周りに間隔を置く*/
  justify-content: center;
  /* 文字の位置 */
  text-align: center;
  box-sizing: border-box;
}



/* 選択肢のリスト1つずつの設定 */
.calc-difference .list-radio li {
  flex-basis: 25%;
  /* 内側の余白 */
  padding: 0 1%;
}



/* 選択肢の画像 */
.calc-difference .list-radio li img {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
}



/* 選択肢部分 */
.calc-difference .list-radio input[type=radio] {
  /* 非表示 */
  display: none;
}



/* 選択肢の装飾 */
.calc-difference .list-radio input[type=radio]:checked+span:before {
  /* 背景色 */
  background-color: #3197ee;
  /* 影 */
  box-shadow: inset 0 0 0 4px #f4f4f4;
}



/* 選択肢部分 */
.calc-difference .list-radio label {
  display: block;
  cursor: pointer;
}



/* 選択肢の文字部分 */
.calc-difference .list-radio label span {
  display: inline-block;
  /* 外側の余白 */
  margin: 0.5em 0;
}



/* 選択肢の装飾（チェックをつけていない状態） */
.calc-difference .list-radio label span:before {
  content: "";
  /* 背景色 */
  background: #f4f4f4;
  /* 角丸 */
  border-radius: 100%;
  /* 線｜太さ｜線種｜色｜ */
  border: 1px solid #b4b4b4;
  display: inline-block;
  /* 横幅 */
  width: 1em;
  /* 高さ */
  height: 1em;
  position: relative;
  /* 表示位置（上基準） */
  top: 0.1em;
  /* 右側の余白 */
  margin-right: 0.2em;
  vertical-align: top;
  /* 文字の位置 */
  text-align: center;
  /* アニメーションの速さ */
  transition: all 250ms ease;
}



/* 強調文字設定 */
.calc-difference .strong {
  /* 文字の大きさ */
  font-size: 1.4em;
  /* 文字の太さ */
  font-weight: 700;
}



/* 横並びの設定 */
.calc-difference .flex {
  display: flex;
  /*水平方向に間隔を配置する方法。
      flex-start = 左側から配置する
      flex-end = 右側から配置する
      center = 真ん中に配置する
      space-around = 均等配置して両端に間隔を置く
      space-between = 均等配置してエリアの間に間隔を置く
      space-evenly = 均等配置して各アイテム周りに間隔を置く*/
  justify-content: center;
  /*垂直方向にの配置位置を設定。
      center = 中央配置
      flex-start = 先頭にまとめる
      flex-end = 末尾にまとめる*/
  align-items: flex-end;
  /* 最大幅 */
  max-width: 100%;
  /* 横幅 */
  width: 100%;
}



/* 初期表示の計算結果部分（非アクティブ時） */
.calc-difference .total {
  display: none;
  /* 文字の位置 */
  text-align: left;
  /* 外側の上余白 */
  margin-top: 16px;
}



/* 初期表示の黒背景部分 */
.calc-difference .total .box-button {
  /* 背景色 */
  background: #000;
  /* 文字の色 */
  color: #fff;
  /* 文字の位置 */
  text-align: center;
  /* 内側の余白 */
  padding: 12px;
  /* 外側の上余白 */
  margin-top: 10px;
}



/* 黒背景内のテキスト */
.calc-difference .total .box-button p {
  /* 文字の大きさ */
  font-size: 1.1em;
  /* 文字の太さ */
  font-weight: 700;
}



/* 黒背景内の「計算する」ボタン */
.calc-difference .total .box-button button {
  display: inline-block;
  /* 背景色 */
  background: #fff;
  /* 文字の色 */
  color: #000;
  /* 角丸 */
  border-radius: 6px;
  /* 線｜太さ｜線種｜色｜ */
  border: none;
  /* 文字の太さ */
  font-weight: 700;
  /* 外側の上余白 */
  margin-top: 1em;
  /* 内側の余白 */
  padding: 0.2em 0.8em;
  cursor: pointer;
}



/* 黒背景内の「計算する」（非アクティブ時） */
.calc-difference .total .box-button button:disabled {
  /* 文字の色 */
  color: #999999;
  cursor: auto;
}



/* 「計算する」ボタンを押下後に表示される部分 */
.calc-difference .difference {
  display: none;
  /* 文字の位置 */
  text-align: left;
  /* 外側の上余白 */
  margin-top: 16px;
}



/* グラフ部分 */
.calc-difference .difference .graph {
  /* 横幅 */
  width: 20%;
  /* 高さ */
  height: 150px;
  display: flex;
  /*水平方向に間隔を配置する方法。
      flex-start = 左側から配置する
      flex-end = 右側から配置する
      center = 真ん中に配置する
      space-around = 均等配置して両端に間隔を置く
      space-between = 均等配置してエリアの間に間隔を置く
      space-evenly = 均等配置して各アイテム周りに間隔を置く*/
  justify-content: space-evenly;
  /* 外側の余白 */
  margin: 0 auto 20px;
  position: relative;

  flex-direction: row;
  /* 下線｜太さ｜線種｜色｜ */
  border-bottom: 2px solid #333;
  /* はみ出た部分は非表示 */
  overflow: hidden;
}



/* 平均値のグラフ（固定値） */
.calc-difference .difference .graph .graph__avg {
  /* 横幅 */
  width: 16px;
  /* 最大幅 */
  max-width: 100px;
  /* 高さ */
  height: auto;
  /* 背景色 */
  background: #E53A40;
  /* 外側の余白 */
  margin: 0;
}



/* 選択された結果によって可変するグラフ（可変値）の外側 */
.calc-difference .difference .graph .graphSaving__box {
  /* 横幅 */
  width: 16px;
  /* 外側の余白 */
  margin: auto 0 0;
  /* アニメーションの設定 */
  animation: 1s ease-out 1 forwards;
  animation-name: chartBar;
  display: block;
  transform-origin: bottom left;
}



/* 選択された結果によって可変するグラフ（可変値） */
.calc-difference .difference .graph .graphSaving__box .graph__saving {
  /* 高さ */
  height: 40px;
  /* 背景色 */
  background: #EFDC05;
  display: block;
}



/* グラフの矢印 */
.calc-difference .difference .graph .savingArrow {
  position: absolute;
  /* 表示位置（上基準） */
  top: 0;
  left: 3.5vw;
  /* あにえーションの設定 */
  animation: 1s ease-out 1 forwards;
  animation-name: arrowAnime;
  /* 回転、拡大縮小（1=100%) */
  transform: rotate(-90deg) scale(0.7);
}



/* パーセントオフ部分 */
.calc-difference .difference .graph .offNum {
  position: absolute;
  /* 表示位置（上基準） */
  top: 50%;
  /* 表示位置（左基準） */
  left: 50%;
  /* 文字の色 */
  color: #45A1CF;
  /* 文字の太さ */
  font-weight: bold;
  /* 文字の大きさ */
  font-size: 16px;
  /* 縁文字 */
  text-shadow: 1px 1px 0 #FFF, -1px -1px 0 #FFF, -1px 1px 0 #FFF, 1px -1px 0 #FFF, 0px 1px 0 #FFF, 0-1px 0 #FFF, -1px 0 0 #FFF, 1px 0 0 #FFF;
  /* 回転、位置 */
  transform: rotate(10deg) translate(-50%, -50%);
  /* 横幅 */
  width: 100%;
  /* 文字の位置 */
  text-align: center;
}



/* パーセントオフ、アクティブ時 */
.calc-difference .difference .graph .offNum.active {
  /* アニメーション */
  animation: num 0.5s 1s 1 forwards;
  /* 透明度 */
  opacity: 0;
}



/* パーセントオフ、数字部分 */
.calc-difference .difference .graph .offNum .num {
  /* 文字の大きさ */
  font-size: 22px;
}



/* 結果のテキスト部分 */
.calc-difference .flex.resultBox {
  /* 横幅 */
  width: 80%;
}



/* 結果のテキスト部分 */
.calc-difference .difference .box-result {
  /* 文字の位置 */
  text-align: right;
  flex-basis: 100%;
}



/* 上側のテキスト */
.calc-difference .difference .box-result .text {
  /* 文字の位置 */
  text-align: left;
}



/* 結果部分 */
.calc-difference .result {
  display: inline-block;
  /* 横幅 */
  width: 100%;
  /* 文字の大きさ */
  font-size: 1.1em;
  /* 文字の位置 */
  text-align: center;
  /* 線｜太さ｜線種｜色｜ */
  border: 1px solid #333;
  /* 文字の色 */
  color: #dc4802;
  /* 内側の余白 */
  padding: 0 0.2em;
  /* 外側の余白 */
  margin: 5px;
}



/* アクティブ時 */
.calc-difference .active {
  display: block;
}



/* 結果がアクティブ時 */
.calc-difference .difference.active {
  display: flex;
  /*水平方向に間隔を配置する方法。
      flex-start = 左側から配置する
      flex-end = 右側から配置する
      center = 真ん中に配置する
      space-around = 均等配置して両端に間隔を置く
      space-between = 均等配置してエリアの間に間隔を置く
      space-evenly = 均等配置して各アイテム周りに間隔を置く*/
  justify-content: center;
  /*垂直方向にの配置位置を設定。
      center = 中央配置
      flex-start = 先頭にまとめる
      flex-end = 末尾にまとめる*/
  align-items: flex-end;
}

/* グラフのアニメーション */
@keyframes chartBar {
  from {
    transform: scaleY(5);
  }

  to {
    transform: scaleY(1);
  }
}

/* 矢印のアニメーション */
@keyframes arrowAnime {

  0%,
  80% {
    opacity: 0;
  }

  100% {
    opacity: 1;
  }
}

/* パーセントオフのアニメーション */
@keyframes num {
  from {
    opacity: 0;
    transform: scale(2) rotate(10deg) translate(0, 0);
  }

  to {
    opacity: 1;
    transform: scale(1) rotate(10deg) translate(-50%, -50%);
  }
}

/*吹き出し（会話形式）[say]*/
.say {
    display: table;
    overflow: hidden;
    width: 100%;
    margin: 1.5em 0;
}

 .faceicon {
    display: table-cell;
    width: 100px;
    padding-right: 20px;
    text-align: center;
    vertical-align: top;
}

 .faceicon img {
    width: 100%;
    height: auto;
    border: solid 3px #eaedf2;
    border-radius: 50%;
}

 .faceicon span {
    font-size: 11px;
    font-weight: bold;
}

 .chatting {
    display: table-cell;
    position: relative;
    width: calc(100% - 100px);
    font-size: 0.95em;
    vertical-align: top;
}

 .sc {
    display: inline-block;
    text-align: left;
    padding: 13px;
    border: solid 2px #d5d5d5;
    border-radius: 12px;
    background: #fff;
    word-break: break-all;
}

 .sc:before {
    display: inline-block;
    position: absolute;
    top: 18px;
    left: -23px;
    border: 12px solid transparent;
    border-right: 12px solid #d5d5d5;
    content: "";
}

 .sc:after {
    display: inline-block;
    position: absolute;
    top: 18px;
    left: -20px;
    border: 12px solid transparent;
    border-right: 12px solid #fff;
    content: "";
}

 .sc p {
    margin: 5px 0;
    padding: 0;
}

.arrow {
  position: relative;
}

.howto_box {
  background: #fbf4eb;
  padding: 5%;
  box-sizing: border-box;
  margin-bottom: 2.3em;
}

.howto_ttl {
  font-weight: bold;
  font-size: 1em;
  border-bottom: 4px solid #e9ae6a;
  margin-bottom: 1em !important;
  padding-bottom: .5em;
  line-height: 1.5;
  color: #4c3a25;
}

ul {
  list-style: none;
  padding-inline-start: 0px !important;
}
